import json, re, hashlib, unicodedata

def norm_for_dedup(text):
    text = unicodedata.normalize('NFC', text).lower()
    # Replace non-alphanumeric with spaces to check core textual identity
    tokens = re.findall(r'\b\w+\b', text)
    return ' '.join(tokens)

records = []
with open('data/pilot/wiki_pilot_3000_cleaned.jsonl', 'r', encoding='utf-8') as f:
    for line in f:
        records.append(json.loads(line))

norm_map = {}
dupes = []
for r in records:
    n = norm_for_dedup(r['text'])
    h = hashlib.sha256(n.encode('utf-8')).hexdigest()
    if h in norm_map:
        dupes.append((norm_map[h], r))
    else:
        norm_map[h] = r

print(f'Total records: {len(records)}')
print(f'Duplicate normalized texts found: {len(dupes)}')
for orig, dup in dupes:
    print(f'  Match: ID {orig[\"id\"]} ({orig[\"title\"]}) == ID {dup[\"id\"]} ({dup[\"title\"]})')
